TIMEOUT_SECONDS = 5

def within_timeout(duration_ms):
    return duration_ms <= TIMEOUT_SECONDS

import unittest
import duration
class DurationTest(unittest.TestCase):
    def test_four_seconds_is_within_five(self): self.assertTrue(duration.within_timeout(4000))
    def test_six_seconds_exceeds_five(self): self.assertFalse(duration.within_timeout(6000))
if __name__ == '__main__': unittest.main()

